const libraryBooks=[
  {id:'elementary',level:'Elementary',cefr:'A1–A2',edition:'Third Edition',authors:'Michael McCarthy · Felicity O’Dell',cover:'covers/elementary.png',accent:'#ff795f',units:elementaryVocabulary,description:'Ingliz tilidagi ilk qadamingiz. Kundalik hayot uchun eng kerakli so‘zlar.'},
  {id:'intermediate',level:'Pre-intermediate & Intermediate',cefr:'B1',edition:'Fourth Edition',authors:'Stuart Redman',cover:'covers/intermediate.png',accent:'#4fd7bb',units:vocabulary,description:'So‘z boyligingizni kengaytiring. Ko‘proq mavzu, ibora va yangi imkoniyatlar.'},
];
for(const book of libraryBooks)for(const u of book.units)u.bookId=book.id;
let selectedBook=null,libraryPage='books';
const bookUnits=()=>selectedBook?.units||vocabulary;
const bookWords=book=>book.units.flatMap(u=>u.words);
const libraryWords=libraryBooks.flatMap(bookWords);
const bookHref=book=>'#book-'+book.id;
const unitHref=(u)=>u.bookId==='elementary'?'#elementary-unit-'+u.number:'#unit-'+u.number;
const checkpointKey=u=>u.bookId==='elementary'?'elementary:'+u.number:String(u.number);
const learningPercent=(known,total)=>total?Math.round(known/total*10000)/100:0;
function bookProgress(book){
  const words=bookWords(book),c=counts(words),reviewed=c.known+c.unknown;
  return {...c,total:words.length,reviewed,percent:learningPercent(c.known,words.length),completed:book.units.filter(completedUnit).length,attempts:words.reduce((n,w)=>n+(progress[w.id]?.attempts||0),0)};
}
function mainNavigation(){return `<div class="library-topbar"><a class="library-brand" href="#books" aria-label="WORDLY"><span class="library-logo">w</span>WORDLY<span class="brand-dot"></span></a><nav class="main-navigation" aria-label="Asosiy menyu"><a href="#books" ${libraryPage==='books'&&!selectedBook?'aria-current="page"':''}>Kutubxona</a><a href="#statistics" ${libraryPage==='statistics'?'aria-current="page"':''}>Statistika</a></nav>${languageControl()}</div>`}
function libraryView(){
  const c=counts(libraryWords),totalUnits=libraryBooks.reduce((n,b)=>n+b.units.length,0);
  return `<section class="library-hero"><div class="library-kicker"><span></span> HAR KUNI BIR QADAM</div><h1>Yangi so‘zlar.<br><span>Yangi imkoniyatlar.</span></h1><p>Darajangizga mos kitobni tanlang.<br>So‘zlarni o‘rganing va o‘sishingizni kuzating.</p><div class="library-summary"><span>${svg('book')}<strong>${libraryBooks.length}</strong> kitob</span><span><strong>${totalUnits}</strong> unit</span><span><strong>${libraryWords.length.toLocaleString('en')}</strong> ta so‘z</span></div></section><section class="bookshelf" aria-labelledby="bookshelf-title"><div class="bookshelf-heading"><div><p class="eyebrow">SIZNING KITOBLARINGIZ</p><h2 id="bookshelf-title">Qaysi kitobdan boshlaymiz?</h2></div><span class="bookshelf-note">Osondan murakkabga ${svg('arrow')}</span></div><div class="book-grid">${libraryBooks.map((book,index)=>bookCard(book,index)).join('')}</div></section><section class="library-bottom"><div class="library-bottom-icon">${svg('spark')}</div><div><strong>Kichik qadamlar katta natijaga yetaklaydi.</strong><p>Hozirgacha <b>${c.known}</b> ta so‘z yodladingiz. Bugun ham davom eting.</p></div><a href="#statistics">Natijalarim ${svg('arrow')}</a></section><footer class="library-footer"><span>WORDLY · English Vocabulary in Use</span><span>Natijalar shu brauzerda saqlanadi.</span></footer>`;
}
function bookCard(book,index){
  const p=bookProgress(book),started=p.reviewed>0;
  return `<a class="book-card" href="${bookHref(book)}" style="--book-accent:${book.accent}" aria-label="${html(book.level)} — Kitobni ochish"><div class="book-card-top"><span class="book-order">0${index+1}</span><span class="level-badge">${book.cefr}</span></div><div class="book-card-content"><div class="book-cover-wrap"><img class="book-cover" src="${book.cover}" alt="English Vocabulary in Use — ${html(book.level)}" width="450" height="610" loading="eager"></div><div class="book-details"><p class="book-series" lang="en">ENGLISH VOCABULARY IN USE</p><h3 lang="en">${html(book.level)}</h3><p class="book-description">${book.description}</p><p class="book-facts"><span>${book.units.length} ta unit</span><span>${p.total.toLocaleString('en')} ta so‘z</span></p></div></div><div class="book-progress-head"><span>${started?'O‘rganish jarayoni':'Yangi boshlanish'}</span><strong>${p.percent}%</strong></div><div class="book-progress-track" role="progressbar" aria-label="${html(book.level)} — yodlangan so‘zlar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.percent}"><i style="width:${p.percent}%"></i></div><div class="book-card-footer"><span><b>${p.known}</b> / ${p.total} yodlangan</span><strong>${started?'Davom etish':'Kitobni ochish'} ${svg('arrow')}</strong></div></a>`;
}
function statisticsView(){
  const c=counts(libraryWords),total=libraryWords.length,reviewed=c.known+c.unknown,completed=libraryBooks.reduce((n,b)=>n+bookProgress(b).completed,0),attempts=libraryWords.reduce((n,w)=>n+(progress[w.id]?.attempts||0),0);
  const recent=libraryWords.filter(w=>progress[w.id]?.updated).sort((a,b)=>progress[b.id].updated-progress[a.id].updated).slice(0,6);
  return `<section class="statistics-heading"><div class="library-kicker"><span></span> HARAKATINGIZ NATIJASI</div><h1>Mening statistikam</h1><p>Har bir o‘rganilgan so‘z — oldinga bir qadam.</p></section><div class="statistics-metrics"><article><span>Yodlangan so‘zlar</span><strong>${c.known}<small> / ${total}</small></strong><p>${learningPercent(c.known,total)}% lug‘at yodlangan</p></article><article><span>Takrorlash kerak</span><strong>${c.unknown}</strong><p>Yana bir bor mashq qiling</p></article><article><span>Tugallangan unitlar</span><strong>${completed}<small> / ${libraryBooks.reduce((n,b)=>n+b.units.length,0)}</small></strong><p>Barcha so‘zlari ko‘rib chiqilgan</p></article><article><span>Jami javoblar</span><strong>${attempts}</strong><p>${reviewed} ta so‘z bilan ishlangansiz</p></article></div><section class="knowledge-panel"><div><h2>So‘zlar holati</h2><span>${total} ta so‘z</span></div><div class="knowledge-track" role="img" aria-label="${c.known} bilaman, ${c.unknown} bilmayman, ${c.new} yangi"><i class="known" style="width:${c.known/total*100}%"></i><i class="unknown" style="width:${c.unknown/total*100}%"></i></div><div class="knowledge-legend"><span><i class="dot known"></i>Bilaman <b>${c.known}</b></span><span><i class="dot unknown"></i>Bilmayman <b>${c.unknown}</b></span><span><i class="dot"></i>Yangi <b>${c.new}</b></span></div></section><div class="statistics-sections"><section class="book-statistics"><h2>Kitoblar bo‘yicha</h2>${libraryBooks.map(book=>{const p=bookProgress(book);return `<a href="${bookHref(book)}" class="book-stat-row" style="--book-accent:${book.accent}"><img src="${book.cover}" width="52" height="71" alt="${html(book.level)}"><div><h3 lang="en">${html(book.level)}</h3><p>${p.known} yodlangan · ${p.unknown} takrorlash kerak</p><div class="book-progress-track"><i style="width:${p.percent}%"></i></div><span>${p.completed} / ${book.units.length} tugallangan unit</span></div><strong>${p.percent}%</strong></a>`}).join('')}</section><section class="recent-words"><h2>Oxirgi o‘rganilgan so‘zlar</h2>${recent.length?recent.map(w=>`<div class="recent-word"><span class="word-icon ${status(w)}">${svg(status(w)==='known'?'check':'close')}</span><div><strong lang="en">${html(w.en)}</strong><p lang="${appLanguage}">${html(meaning(w))}</p></div><span>${statusLabel(status(w))}</span></div>`).join(''):`<div class="statistics-empty">${svg('book')}<p>Hali so‘z o‘rganilmagan.<br>Kitob tanlab, birinchi mashqni boshlang.</p><a href="#books" class="button primary">Kitob tanlash ${svg('arrow')}</a></div>`}</section></div><p class="statistics-storage">Natijalar shu brauzerda saqlanadi.</p>`;
}
